<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import{api}from'../api';import type{Post}from'../types';import MarkdownView from'../components/MarkdownView.vue';const route=useRoute(),post=ref<Post>(),error=ref('');onMounted(async()=>{try{post.value=await api('/posts/'+route.params.slug)}catch{error.value='文章不存在或尚未发布'}});const headings=computed(()=>post.value?.contentMarkdown.split('\n').filter(x=>/^#{2,3} /.test(x)).map(x=>x.replace(/^#+ /,''))||[])</script><template><p v-if="error" class="state">{{error}}</p><article v-else-if="post" class="article"><RouterLink to="/posts">← 返回文章列表</RouterLink><header><div class="meta">{{post.category}} · {{post.readingMinutes}} 分钟阅读</div><h1>{{post.title}}</h1><p>{{post.summary}}</p><time>{{post.publishedAt?.slice(0,10)}}</time><div class="tags"><span v-for="t in post.tags" :key="t">#{{t}}</span></div></header><aside v-if="headings.length"><strong>本页目录</strong><div v-for="h in headings" :key="h">{{h}}</div></aside><MarkdownView :content="post.contentMarkdown"/></article><p v-else class="state">正在读取文章…</p></template>
